using ModelContextProtocol.Server;
using System.ComponentModel;

namespace HttpMcpServer.Tools;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Greets a user by name with an optional custom message.")]
    public static string Greet(
        [Description("The name of the person to greet")] string name,
        [Description("Optional custom greeting phrase (defaults to 'Hello')")] string greeting = "Hello")
    {
        return $"{greeting}, {name}! Welcome to the MCP server.";
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace HttpMcpServer.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Features = new
            {
                GreetingEnabled = true,
                MaxNameLength = 100
            }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://supported-languages",
        Name = "Supported Languages",
        MimeType = "application/json"),
     Description("Returns the list of supported languages.")]
    public static string GetSupportedLanguages()
    {
        var languages = new[] { "en", "es", "fr", "de", "ja" };
        return JsonSerializer.Serialize(languages);
    }
}

